// Calls the independent, read-only C parser shipped by the firmware, as wasm.
// A pinned parser must accept the exact generated bytes before they are returned.
import {sha} from './bytes.ts'

export type SmzValidatorPin={kind:'core-parser-wasm';api:1;file:string;sha256:string;contract:number;coreVersion:string}
type Parser={memory:WebAssembly.Memory;synfact_smz_api:()=>number;synfact_smz_contract:()=>number;
 synfact_smz_input:()=>number;synfact_smz_validate:(pointer:number,length:number)=>number;synfact_smz_failure:()=>number}
const instances=new Map<string,Promise<Parser>>()

export function checkValidatorPin(value:any):SmzValidatorPin {
 if(!value||value.kind!=='core-parser-wasm'||value.api!==1||typeof value.file!=='string'||
   !/^[\w.-]+\.wasm$/.test(value.file)||!/^[0-9a-f]{64}$/.test(value.sha256)||
   !Number.isInteger(value.contract)||value.contract<=0||value.contract>0xffffffff||
   typeof value.coreVersion!=='string'||!value.coreVersion.length)throw Error('Invalid core parser pin')
 return value
}

async function load(bytes:Uint8Array):Promise<Parser>{
 const module=await WebAssembly.compile(bytes as BufferSource)
 if(WebAssembly.Module.imports(module).length)throw Error('The core parser must have no imports')
 const instance=await WebAssembly.instantiate(module,{})
 const parser=instance.exports as unknown as Parser
 if(!(parser.memory instanceof WebAssembly.Memory)||
   ['synfact_smz_api','synfact_smz_contract','synfact_smz_input','synfact_smz_validate','synfact_smz_failure']
    .some(name=>typeof instance.exports[name]!=='function')||parser.synfact_smz_api()!==1)
   throw Error('Invalid core parser exports')
 return parser
}

export async function validateSmz(data:Uint8Array,pin:SmzValidatorPin,fetch:(name:string)=>Promise<Uint8Array>):Promise<void>{
 checkValidatorPin(pin)
 const bytes=await fetch(pin.file)
 if(bytes.length>512*1024||sha(bytes)!==pin.sha256)throw Error('Core parser hash mismatch')
 let pending=instances.get(pin.sha256)
 if(!pending){
   if(instances.size>=4)instances.delete(instances.keys().next().value!)
   pending=load(bytes).catch(error=>{instances.delete(pin.sha256);throw error});instances.set(pin.sha256,pending)
 }
 const parser=await pending
 if((parser.synfact_smz_contract()>>>0)!==pin.contract)throw Error('The core parser and catalog have different compatibility contracts')
 const at=parser.synfact_smz_input()>>>0,end=at+data.length
 if(!at||data.length>16*1024*1024||end>18*1024*1024)throw Error('Mods bank exceeds core parser memory bounds')
 if(parser.memory.buffer.byteLength<end)parser.memory.grow(Math.ceil((end-parser.memory.buffer.byteLength)/65536))
 new Uint8Array(parser.memory.buffer,at,data.length).set(data)
 let valid:number
 try{valid=parser.synfact_smz_validate(at,data.length)}catch(error){instances.delete(pin.sha256);throw error}
 if(valid!==1)throw Error(`The core rejected the generated mods bank (check ${parser.synfact_smz_failure()>>>0}). No mods file was returned.`)
}
